// Load content prompt + content-creation skill + localization insights
const input = $input.first().json;
const context = {
  system_prompt: '{{ content-generation prompt }}',
  skill: '{{ content-creation skill }}',
  content_brief: input.content_brief || {},
  localized_insights: input.localized_insights || {},
  few_shot_examples: input.few_shot_examples || [],
  query_id: input.query_id
};
return { json: context };

// Validate against content-output schema
const response = $input.first().json;
const content = response.content?.[0]?.text || response.content || '{}';
let output;
try {
  output = typeof content === 'string' ? JSON.parse(content) : content;
} catch (e) {
  output = { query_id: $json.query_id, error: 'Invalid JSON output' };
}
output.agent_name = 'content_generation';
output.model_used = 'claude-3-5-sonnet-20241022';
return { json: output };
